    const name = id => state.snapshot?.state?.actors?.find(a => a.id === id)?.name || id || 'Character';
    if (event.event_type === 'character.moved') return `${name(p.character_id)} moved to ${p.to?.x}, ${p.to?.y}.`;
    if (event.event_type === 'attack.resolved') return `${name(p.attacker_id)} attacked ${name(p.target_id)}. Roll ${p.roll} + ${Number(p.total) - Number(p.roll)} = ${p.total}. ${p.hit ? `Hit for ${p.damage} damage. ${p.remaining_hp} HP remaining.` : 'Miss. No damage dealt.'}`;
    if (event.event_type === 'object.interacted') return p.result || 'The old bridge was investigated.';
    if (event.event_type === 'turn.advanced') return `Round ${p.round}. ${name(p.active_actor_id)} is active.`;
    if(event.event_type==='dice.roll') return `${p.by} rolled ${p.formula}: [${(p.rolls||[]).join(', ')}] = ${p.total}.`;
    if(event.event_type==='chat.send') return `${p.by}: ${p.message}`;
    if(event.event_type==='notes.save') return 'Session notes saved.';
    if(event.event_type==='map.block') return `Terrain ${p.enabled?'blocked':'opened'} at ${p.point?.x}, ${p.point?.y}.`;
    if(event.event_type==='map.fog') return `Fog planning cell ${p.enabled?'marked':'cleared'}.`;
    if(event.event_type==='map.ping') return `${p.by} pinged ${p.point?.x}, ${p.point?.y}.`;
    if(event.event_type==='map.draw') return 'Map annotation saved.';
    if(event.event_type==='map.undo') return 'Last annotation removed.';
    if(event.event_type==='map.upload') return 'Custom battle map saved.';
