  document.addEventListener('keydown',event=>{const tab=event.target.closest('[data-inspector-tab]');if(!tab||!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const tabs=['actions','characters','tools','table','log'],index=tabs.indexOf(tab.dataset.inspectorTab),next=event.key==='Home'?0:event.key==='End'?4:(index+(event.key==='ArrowRight'?1:4))%5;selectInspectorTab(tabs[next]);document.querySelector(`[data-inspector-tab="${tabs[next]}"]`)?.focus();});
