  document.addEventListener('input',event=>{const form=event.target.closest('[data-tool-form]');if(!form)return;state.toolDrafts??={};state.toolDrafts[form.dataset.toolForm]=Object.fromEntries(new FormData(form));if(form.elements.hostile)state.toolDrafts[form.dataset.toolForm].hostile=form.elements.hostile.checked;});
